// Touch joystick for movement; drag across the right side of the scene to look around.
const touchPad=document.querySelector('#touchPad'),touchPadKnob=document.querySelector('#touchPadKnob');let padPointer=null;
function moveWithPad(e){const rect=touchPad.getBoundingClientRect(),radius=42;let dx=e.clientX-(rect.left+rect.width/2),dy=e.clientY-(rect.top+rect.height/2);const length=Math.hypot(dx,dy);if(length>radius){dx=dx/length*radius;dy=dy/length*radius}touchPadKnob.style.transform=`translate(${dx}px,${dy}px)`;keys.KeyA=dx/radius<-.22;keys.KeyD=dx/radius>.22;keys.KeyW=dy/radius<-.22;keys.KeyS=dy/radius>.22}
touchPad.addEventListener('pointerdown',e=>{if(!started||panelOpen())return;padPointer=e.pointerId;touchPad.setPointerCapture(e.pointerId);moveWithPad(e);e.preventDefault()});touchPad.addEventListener('pointermove',e=>{if(e.pointerId===padPointer)moveWithPad(e)});function releasePad(e){if(e.pointerId!==padPointer)return;padPointer=null;keys.KeyW=keys.KeyA=keys.KeyS=keys.KeyD=false;touchPadKnob.style.transform='translate(0,0)'}touchPad.addEventListener('pointerup',releasePad);touchPad.addEventListener('pointercancel',releasePad);
let touchStart=null;canvas.addEventListener('touchstart',e=>{if(!started||panelOpen()||!e.touches.length)return;const t=e.touches[0];touchStart={id:t.identifier,x:t.clientX,y:t.clientY,rx:camera.rotation.x,ry:camera.rotation.y}}, {passive:true});canvas.addEventListener('touchmove',e=>{if(!touchStart||!started||panelOpen())return;const t=Array.from(e.touches).find(touch=>touch.identifier===touchStart.id);if(!t)return;const dx=t.clientX-touchStart.x,dy=t.clientY-touchStart.y;camera.rotation.y=touchStart.ry-dx*.004;camera.rotation.x=THREE.MathUtils.clamp(touchStart.rx-dy*.003,-1.2,1.2)}, {passive:true});canvas.addEventListener('touchend',e=>{if(Array.from(e.changedTouches).some(t=>t.identifier===touchStart?.id))touchStart=null});canvas.addEventListener('touchcancel',()=>{touchStart=null});

